var n=`0251-sheftalia`;var a=`world-0251`;var t=`CY`;var l=`western-asia`;var o=4;var r=50;var s={en:`Sheftalia`,ua:`Шефталія`};var g={en:`A sheftalia-inspired version wrapped in bacon rather than caul fat, which is absent from the catalog.`,ua:`Варіант шефталії, де замість сальника, відсутнього в каталозі, використано бекон.`};var d=[{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:12,i:[[`ground-pork`,450,`g`],[`yellow-onion`,150,`g`],[`parsley`,18,`g`],[`ground-cinnamon`,3,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:18,i:[[`bacon`,250,`g`]]},{en:`Grill over medium-high heat for about 17 minutes, turning regularly until charred outside and safely cooked inside.`,ua:`Смажте на грилі на середньо-сильному жарі приблизно 17 хвилин, регулярно перевертаючи до рум’яної скоринки та повної готовності всередині.`,t:[`grilling`],m:17,i:[[`extra-virgin-olive-oil`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon`,1,`pcs`],[`pita-bread`,280,`g`]]}];var u={slug:n,id:a,country:`CY`,region:l,servings:4,minutes:50,title:s,text:g,steps:d};export{t as country,u as default,a as id,r as minutes,l as region,o as servings,n as slug,d as steps,g as text,s as title};